use super::*;
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn points(node:&DrawingLayerNode,chain:&mut Vec<[f64;6]>,out:&mut Vec<[f64;2]>){chain.push(semio_s_artifact_draw_drawing_model::drawing_transform_to_matrix(&semio_s_artifact_draw_drawing_model::layer_base(node).transform));match node{DrawingLayerNode::Group(group)=>for child in &group.children{points(child,chain,out)},DrawingLayerNode::Path(path)=>for segment in &path.segments{let controls:&[[f64;2]]=match segment{PathSegment::Move{to}|PathSegment::Line{to}|PathSegment::Arc{to,..}=>std::slice::from_ref(to),PathSegment::Quad{ctrl,to}=>{let mut p=*ctrl;for m in chain.iter().rev(){p=[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]]}out.push(p);std::slice::from_ref(to)},PathSegment::Cubic{ctrl1,ctrl2,to}=>{for c in[ctrl1,ctrl2]{let mut p=*c;for m in chain.iter().rev(){p=[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]]}out.push(p)}std::slice::from_ref(to)},PathSegment::Close=>&[]};for control in controls{let mut p=*control;for m in chain.iter().rev(){p=[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]]}out.push(p)}},_=>{}}chain.pop();}
#[test]
fn neutral_geometry_matches_independent_three_and_intrinsic_sharp_witnesses(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["scenes"].as_array().unwrap(){let scene:VectorScene=decode(&row["scene"]);let background=scene.canvas.background.is_some();let mut work=0;let doc=lift_vector_scene(scene,corpus["documentId"].as_str().unwrap().into(),&mut |_|{work+=1;true}).unwrap();let mut actual=Vec::new();for layer in doc.layers.iter().skip(usize::from(background)){points(layer,&mut Vec::new(),&mut actual)}let expected:Vec<[f64;2]>=serde_json::from_value(row["oracleWorldPoints"].clone()).unwrap();assert_eq!(actual.len(),expected.len());for(a,b)in actual.iter().zip(expected){for i in 0..2{assert!((a[i]-b[i]).abs()<=1e-9*a[i].abs().max(b[i].abs()).max(1.0),"{}",row["name"])}}if row.get("expectedAsset").is_some(){let asset=doc.assets.get("image-import-1").unwrap();assert_eq!(asset.width,2);assert_eq!(asset.height,1);assert_eq!(asset.samples.iter().copied().collect::<Vec<_>>(),vec![[255,0,0,128],[0,255,0,64]]);}for cut in[0,1,3,work-1]{let mut at=0;let scene:VectorScene=decode(&row["scene"]);let result=lift_vector_scene(scene,"original-child-target".into(),&mut |_|{let permitted=at<cut.min(work-1);at+=1;permitted});assert_eq!(result.unwrap_err(),"layout.interchange.cancelled");}}}
#[test]
fn unsupported_neutral_semantics_refuse_before_publishing_any_member(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["refusals"].as_array().unwrap(){let mut scene=corpus["scenes"][0]["scene"].clone();if row.get("edit").is_some(){scene["layers"][0]["root"]["transform"]["rotation"]["x"]=row["edit"]["value"].clone()}else{scene["layers"][0]["root"]=row["node"].clone()}let scene:VectorScene=decode(&scene);assert_eq!(lift_vector_scene(scene,"original-child-target".into(),&mut |_|true).unwrap_err(),row["error"].as_str().unwrap());}}
